186	 * 状态机（1s tick）
187	 ****************************************************************************/
188	
189	static void health_tick_cb(lv_timer_t *timer)
190	{
191	    (void)timer;
192	
193	    /* 跨天：清零今日计数并保存 */
194	    int day = today_stamp();
195	    if (g_state_day == 0)
196	        g_state_day = day;
197	    else if (day != g_state_day)
198	    {
199	        g_state_day = day;
200	        g_water_count_today = 0;
201	        g_stand_count_today = 0;
202	        g_seat_today_s = 0;
203	        health_state_save();
204	        LV_LOG_USER("[health] new day %d, counters reset", day);
205	    }
206	
207	    /* ── 在座感知（prox 判据 + 防抖）── */
208	    int prox = dm_prox_get_cm();
209	    if (prox < 0)
210	    {
211	        /* 2026-08-27：传感器不可用（LD2410B 未接入/串口失败）——
212	         * 不启动健康会话：不播欢迎语、不开始计时（用户要求：
213	         * 没有人体传感器就不要开始响应和计时）。等传感器恢复才响应。 */
214	        if (!g_prox_fallback)
215	        {
216	            g_prox_fallback = true;
217	            LV_LOG_WARN("[health] prox sensor unavailable, session idle (no greet/timer)");
218	        }
219	        /* 保持 g_seated 现状（开机为 false）：不 fallback seated，
220	         * 欢迎语（PRESENCE=1）与健康计时都不会启动 */
221	    }
222	    else
223	    {
224	        /* 2026-08-27：dm_prox_get_cm() 只回 0/99/-1 三态（阈值判断在
225	         * luncher_dm.c 内部按 ld2410_seat_cm 完成），此处 prox==0 即"有人
226	         * 且在座距离内"——原 prox<=prox_seat_cm(30) 死配置已删 */
227	        if (prox == 0)
228	        {
229	            g_absent_cnt = 0;
230	            g_leaving = false;   /* P102：回到感应区，恢复倒计时 */
231	            if (!g_seated)
232	            {
233	                if (++g_seat_cnt >= CFG_I("prox_seat_debounce_s", PROX_SEAT_DEBOUNCE_S))
234	                {
235	                    g_seat_cnt = 0;
236	                    health_session_start();
237	                }
238	            }
239	        }
240	        else
241	        {
242	            g_seat_cnt = 0;
243	            if (g_seated)
244	            {
245	                /* P102：离开感应区 → 立即暂停倒计时（防抖满才清零） */
246	                g_leaving = true;
247	                if (++g_absent_cnt >= CFG_I("prox_absent_debounce_s", PROX_ABSENT_DEBOUNCE_S))
248	                {
249	                    g_absent_cnt = 0;
250	                    health_session_end();
251	                }
252	            }
253	        }
254	    }
255	
256	    /* 每秒 RING（含未在座）：双圈/健康卡/prox debug 实时刷新——
257	     * 2026-08-15：prox 调试显示不依赖坐下，RING 提前到 g_seated 判断前 */
258	    health_evt(DM_HEALTH_EVT_RING, 0);
259	
260	    /* ── 在座时：累计 + 双提醒倒计时（P102：离开感应中 g_leaving 暂停）── */
261	    if (!g_seated || g_leaving)
262	        return;
263	
264	    g_seat_today_s++;
265	
266	    /* 喝水：未触发时倒计时；触发后等按钮（remain=0 停住） */
267	    if (g_water_remain_s > 0)
268	    {
269	        g_water_remain_s--;
270	        if (g_water_remain_s == 0)
271	        {
272	            g_water_level++;
273	            LV_LOG_USER("[health] water popup L%d", g_water_level);
274	            health_evt(DM_HEALTH_EVT_WATER_POP, g_water_level);
275	        }
276	    }
277	
278	    /* 久坐 */
279	    if (g_sit_remain_s > 0)
280	    {
281	        g_sit_remain_s--;
282	        if (g_sit_remain_s == 0)
283	        {
284	            g_sit_level++;
