94	 ****************************************************************************/
95	
96	static int cfg_find(const char *key)
97	{
98	    for (int i = 0; i < g_cfg_count; i++)
99	        if (strcmp(g_cfg[i].key, key) == 0)
100	            return i;
101	    return -1;
102	}
103	
104	static int cfg_upsert(const char *key, const char *val)
105	{
106	    int i = cfg_find(key);
107	    if (i >= 0)
108	        {
109	            strncpy(g_cfg[i].val, val, DM_CFG_VAL_MAX - 1);
110	            g_cfg[i].val[DM_CFG_VAL_MAX - 1] = '\0';
111	            return 0;
112	        }
113	    if (g_cfg_count >= DM_CFG_MAX_ENTRIES)
114	        return -1;
115	    strncpy(g_cfg[g_cfg_count].key, key, DM_CFG_KEY_MAX - 1);
116	    g_cfg[g_cfg_count].key[DM_CFG_KEY_MAX - 1] = '\0';
117	    strncpy(g_cfg[g_cfg_count].val, val, DM_CFG_VAL_MAX - 1);
118	    g_cfg[g_cfg_count].val[DM_CFG_VAL_MAX - 1] = '\0';
119	    g_cfg_count++;
120	    return 0;
121	}
122	
123	/* 去掉行首/行尾空白 */
124	static char *cfg_trim(char *s)
125	{
126	    while (*s == ' ' || *s == '\t')
127	        s++;
128	    size_t len = strlen(s);
129	    while (len > 0 && (s[len - 1] == ' ' || s[len - 1] == '\t' ||
130	                       s[len - 1] == '\r' || s[len - 1] == '\n'))
131	        s[--len] = '\0';
132	    return s;
133	}
134	
135	static void cfg_write_file(void)
136	{
137	    FILE *f = fopen(DM_HEALTH_CFG_FILE, "w");
138	    if (!f)
139	        return;
140	    for (int i = 0; i < g_cfg_count; i++)
141	        fprintf(f, "%s=%s\n", g_cfg[i].key, g_cfg[i].val);
142	    fclose(f);
143	}
144	
145	static void cfg_write_template(void)
146	{
147	    FILE *f = fopen(DM_HEALTH_CFG_FILE, "w");
148	    if (!f)
149	        return;
150	    for (int i = 0; g_cfg_template[i]; i++)
151	        fprintf(f, "%s\n", g_cfg_template[i]);
152	    fclose(f);
153	    LV_LOG_USER("[cfg] template written to %s", DM_HEALTH_CFG_FILE);
154	}
155	
156	static void cfg_load_file(void)
157	{
158	    FILE *f = fopen(DM_HEALTH_CFG_FILE, "r");
159	    if (!f)
160	        return;
161	    char line[DM_CFG_KEY_MAX + DM_CFG_VAL_MAX + 8];
162	    while (fgets(line, sizeof(line), f))
163	    {
164	        char *p = cfg_trim(line);
165	        if (*p == '\0' || *p == '#')
166	            continue;
167	        char *eq = strchr(p, '=');
168	        if (!eq)
169	            continue;
170	        *eq = '\0';
171	        char *key = cfg_trim(p);
172	        char *val = cfg_trim(eq + 1);
173	        if (*key && *val)
174	            cfg_upsert(key, val);
175	    }
176	    fclose(f);
177	}
