collect_ctx：
```c
static voice_ctx_t collect_ctx(void)
{
    voice_ctx_t c;
    memset(&c, 0, sizeof(c));
    time_t now = time(NULL);
    struct tm tm;
    localtime_r(&now, &tm);

    c.seated         = dm_health_is_seated();
    c.sit_s          = (int)dm_health_seat_s();
    c.today_sit_cnt  = dm_health_sit_cnt_today();
    c.water_cnt      = dm_health_water_count();
    c.stand_cnt      = dm_health_stand_count();
    c.away_s         = (int)dm_health_last_away_s();
    c.decline_cnt    = dm_health_decline_cnt();
    c.since_voice_s  = g_last_voice_ts ? (int)(now - g_last_voice_ts) : 0x7fffffff;
    c.since_ai_s     = g_ai_ts ? (int)(now - g_ai_ts) : 0x7fffffff;
    c.music_playing  = g_music_playing;
    c.hour           = tm.tm_hour;
    memcpy(c.budget, g_budget, sizeof(g_budget));
    memcpy(c.recent_ids, g_recent_ids, sizeof(g_recent_ids));
    return c;
}
```

classify_scene（规格 §5.3）：
```c
static int classify_scene(const voice_ctx_t *c)
{
    if (c->since_ai_s <= CFG_I("recent_ai_interaction_cooldown", 300)) return 10;
    if (c->music_playing && CFG_I("music_sit_silent", 1))               return 11;
    if (!c->seated)                                                     return 0;
    if (!g_boot_greet_done)                                             return 1;
    if (c->today_sit_cnt == 1)                                          return 2;
    if (c->away_s <= CFG_I("away_short_max_s", 300))                    return 4;
    if (c->away_s >= CFG_I("away_long_min_s", 1800))                    return 5;
    if (c->decline_cnt > 0 && c->away_s <= CFG_I("decline_revisit_s", 900)) return 12;
    if (c->sit_s >= CFG_I("sit_long_for_revisit_s", 3600))              return 6;
    if (c->today_sit_cnt >= CFG_I("sit_cnt_quiet_th", 6))               return 7;
    if (c->hour >= 23 || c->hour < 5)                                   return 9;
    if (c->hour >= 18)                                                  return 8;
    return 3;
}
```
注意规格 §5.3 里场景 6 是 sat_long_before_away（离开前坐得久）——用 sit_s（今日累计≈连续坐姿）≥3600 近似（离开前坐姿没法直接拿到，用 sit_s 近似：坐满 1h 后离开回来 → 场景 6）。declined_recently：decline_cnt>0 且 away_s <= decline_revisit_s（拒绝后短时间回来）。ok 近似。

