pick_category（坐下场景 3~9/12 在 teasing/caring/system_response 选）：
```c
static voice_category_t pick_category(int scene, const voice_ctx_t *c)
{
    if (scene <= 2) return CAT_GREETING;
    /* 加权：时段权重（cfg W 组）× 基础 */
    int w_tease = 50, w_care = 50, w_tiny = 10;
    /* 时段系数 */
    const char *tag = "morning";
    if (c->hour >= 10 && c->hour < 11) tag = "forenoon";
    else if (c->hour >= 11 && c->hour < 14) tag = "noon";
    else if (c->hour >= 14 && c->hour < 18) tag = "afternoon";
    else if (c->hour >= 18 && c->hour < 23) tag = "evening";
    else if (c->hour >= 23 || c->hour < 5) tag = "night";
    w_tease = weight_key(tag, "teasing", 50);
    w_care  = weight_key(tag, "caring", 50);
    w_tiny  = 10;  /* 粒子基础低 */
    /* budget 修正：teasing 将满 → 降权 */
    if (budget_full(CAT_TEASING)) w_tease = 0;
    if (budget_full(CAT_CARING)) w_care = 0;
    /* 深夜只短句/粒子 → 排除 teasing？设计说深夜少话、关心为主。teasing 权重已低（0.2）*/
    if (c->hour >= 23 || c->hour < 5) w_tease = 0;
    int total = w_tease + w_care + w_tiny;
    int r = rand() % (total + 1);  /* 0..total */
    if (r < w_tease) return CAT_TEASING;
    if (r < w_tease + w_care) return CAT_CARING;
    return CAT_SYSTEM_RESPONSE;
}
```
