```c
static int cfg_float_x100(const char *key, float def)
{
    const char *s = dm_health_cfg_get_str(key, NULL);
    if (!s) return (int)(def * 100);
    char *end = NULL;
    float v = strtof(s, &end);
    if (end == s) return (int)(def * 100);
    return (int)(v * 100);
}
