weighted_select（规格 §5.5）：
```c
static const char *weighted_select(voice_category_t cat, const voice_ctx_t *c)
{
    int cand[6], cnt = 0;
    for (int i = 0; i < g_pool_cnt[cat]; i++) {
        /* 剔除最近播放 */
        int recent = 0;
        for (int r = 0; r < 8; r++)
            if (g_recent_ids[r] && strcmp(g_recent_ids[r], g_pool[cat][i].name) == 0) { recent = 1; break; }
        if (recent) continue;
        cand[cnt++] = i;
    }
    if (cnt == 0) return NULL;  /* 全在冷却/历史里 → UI_ONLY */
    /* 加权随机（基础权重，可再乘时段系数——简化：基础权重直接当 weight） */
    int total = 0;
    for (int i = 0; i < cnt; i++) total += g_pool[cat][cand[i]].weight;
    int r = rand() % total;
    for (int i = 0; i < cnt; i++) {
        r -= g_pool[cat][cand[i]].weight;
        if (r < 0) return g_pool[cat][cand[i]].name;
    }
    return g_pool[cat][cnt - 1].name;
}
```

decide（规格 §5.2）：
```c
voice_decision_t voice_director_decide(const voice_ctx_t *ctx)
{
    voice_decision_t d = { VOICE_NONE, 0, NULL };
    int scene = classify_scene(ctx);
    /* 时段限播计数更新 */
    update_period(ctx->hour);
    if (!pass_silence_checks(ctx, scene))
        return d;
    voice_category_t cat = pick_category(scene, ctx);
    const char *wav = weighted_select(cat, ctx);
    if (!wav) { d.action = VOICE_UI_ONLY; d.category = cat; return d; }
    d.action = action_of(cat);
    d.category = cat;
    d.wav = wav;
    return d;
}
```
