```c
static int g_period = -1, g_period_cnt;
static void update_period(int hour)
{
    int p = (hour >= 5 && hour < 11) ? 0 : (hour >= 11 && hour < 14) ? 1 :
            (hour >= 14 && hour < 18) ? 2 : (hour >= 18 && hour < 23) ? 3 : 4;
    if (p != g_period) { g_period = p; g_period_cnt = 0; }
}
static bool period_cnt_full(void)
{
    int limit = CFG_I("greet_max_per_period", 2);
    return g_period_cnt >= limit;
}
