```c
static void health_sit_greeting(void)
{
    const char *msg;
    const char *tone;   /* P102：本地提示音 wav 名（cfg key 同名 /resource/tones/） */

    if (!g_health_welcome_done)
    {
        g_health_welcome_done = true;
        msg = dm_health_cfg_get_str("greet_first",
              "欢迎使用牛马健康助理，祝你年年有今日，岁岁有今朝啊。");
        tone = "greet_first";
        dm_tone_play(tone);
        LV_LOG_USER("[health] greeting: welcome -> %s", msg);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    int h = tm.tm_hour;
    int period = health_greet_period(h);

    /* P103：时间未就绪（WiFi 未连/对时未完成）→ 不按时段播欢迎语，
     * 标记待补播；对时完成后由 weather_update_cb 补播一次。 */
    if (!g_greet_time_ready)
    {
        g_greet_pending = true;
        LV_LOG_USER("[health] greeting: %d:00 deferred (time not synced)", h);
        return;
    }

    /* P102：每时段限播（离座再入座不重复提醒），跨时段重置 */
    if (period != g_greet_period)
    {
        g_greet_period = period;
        g_greet_period_cnt = 0;
    }
    if (g_greet_period_cnt >= dm_health_cfg_get_int("greet_max_per_period", 2))
    {
        LV_LOG_USER("[health] greeting: %d:00 silent (period %d, cnt=%d >= limit)",
                    h, period, g_greet_period_cnt);
        return;
    }
    g_greet_period_cnt++;

    if (h >= 5 && h < 11)
    {
        msg = dm_health_cfg_get_str("greet_morning",
              "坐得可真早啊，今天又是当牛做马的一天，准备好把自己干废了吗？");
        tone = "greet_morning";
    }
    else if (h >= 11 && h < 14)
    {
        msg = dm_health_cfg_get_str("greet_noon",
              "饭点都过了还坐着，牛马也是要吃饭的，快去补充点燃料。");
        tone = "greet_noon";
    }
    else if (h >= 14 && h < 18)
    {
        msg = dm_health_cfg_get_str("greet_afternoon",
              "下午好，腰还好吗？别急，过两小时我再提醒你起来活动。");
        tone = "greet_afternoon";
    }
    else if (h >= 18 && h < 23)
    {
        msg = dm_health_cfg_get_str("greet_evening",
              "天都黑了还在卷，这工位是焊在你身上了吗？");
        tone = "greet_evening";
    }
    else
    {
        msg = dm_health_cfg_get_str("greet_night",
              "这个点了还坐着？你真是牛马里的战斗牛马啊。");
        tone = "greet_night";
    }

    dm_tone_play(tone);
    LV_LOG_USER("[health] greeting: %d:00 -> %s", h, msg);
}
```
