static void health_sit_greeting(void)
{
    const char *msg;
    const char *tone;   /* P102：本地提示音 wav 名（cfg key 同名 /resource/tones/） */

    if (!g_health_welcome_done)
    {
        g_health_welcome_done = true;
        msg = dm_health_cfg_get_str("greet_first",
              "欢迎使用牛马健康助理，祝你年年有今日，岁岁有今朝啊。");
        tone = "greet_first";
        dm_tone_play(tone);
        LV_LOG_USER("[health] greeting: welcome -> %s", msg);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    int h = tm.tm_hour;
